// 由 scripts/gen-theme-pack.cjs 自动生成，请勿手改
window.CNBLOG_THEME = {
  "files": {
    "themes/cnblog/layout/archive.ejs": "<%\r\n  // 归档 / 分类 / 标签共用一个模板：\r\n  // 分页（每页条数由 _config.yml 的 *_generator.per_page 决定）、按年份分组、标题后跟摘要\r\n  var groupByYear = true;\r\n  var currentYear = '';\r\n%>\r\n<article class=\"post-card archive-page\">\r\n  <h1 class=\"post-title\">\r\n    <% if (is_category()) { %>分类：<%- page.category %>\r\n    <% } else if (is_tag()) { %>标签：<%- page.tag %>\r\n    <% } else { %>归档<% } %>\r\n  </h1>\r\n\r\n  <% if (page.posts && page.posts.length) { %>\r\n    <%\r\n      // 分类页希望和仓库文件夹里的顺序一致：先看 front-matter 的 order，再退回文件名；\r\n      // 归档/标签页保持 Hexo 默认的日期倒序。\r\n      var listedPosts;\r\n      if (is_category() && typeof page.posts.toArray === \"function\") {\r\n        listedPosts = page.posts.toArray().sort(function (a, b) {\r\n          var ao = a.order != null ? Number(a.order) : Infinity;\r\n          var bo = b.order != null ? Number(b.order) : Infinity;\r\n          if (ao !== bo) return ao - bo;\r\n          return String(a.source || \"\").localeCompare(String(b.source || \"\"), \"zh\");\r\n        });\r\n      } else {\r\n        listedPosts = typeof page.posts.toArray === \"function\" ? page.posts.toArray() : page.posts;\r\n      }\r\n    %>\r\n    <% listedPosts.forEach(function (post) { %>\r\n      <% if (groupByYear) {\r\n           var y = date(post.date, 'YYYY');\r\n           if (y !== currentYear) { currentYear = y; %>\r\n             <h2 class=\"archive-year\"><%- y %></h2>\r\n      <%   }\r\n         } %>\r\n      <div class=\"archive-item\">\r\n        <div class=\"archive-head\">\r\n          <time class=\"archive-date\"><%- date(post.date, 'MM-DD') %></time>\r\n          <a class=\"archive-title\" href=\"<%- url_for(post.path) %>\"><%- post.title %></a>\r\n        </div>\r\n        <%\r\n          // 摘要优先级：手填 excerpt > abstract > 正文自动截取\r\n          // 加密文章的正文是密文，绝不能拿 content 截取\r\n          var rawSummary = post.excerpt || post.abstract || post.description || '';\r\n          if (!rawSummary && !post.password) rawSummary = post.content || '';\r\n          // 去掉 KaTeX 的 MathML 副本，否则摘要里公式会出现两遍\r\n          rawSummary = String(rawSummary).replace(/<span class=\"katex-mathml\">[\\s\\S]*?<\\/math><\\/span>/g, '');\r\n          var summary = strip_html(rawSummary).replace(/\\s+/g, ' ').trim();\r\n        %>\r\n        <% if (summary) { %>\r\n          <div class=\"archive-excerpt\"><%- truncate(summary, { length: 120 }) %></div>\r\n        <% } %>\r\n      </div>\r\n    <% }) %>\r\n  <% } else { %>\r\n    <p class=\"empty-tip\">还没有文章。</p>\r\n  <% } %>\r\n\r\n  <% if (page.total > 1) { %>\r\n    <nav class=\"pagination\">\r\n      <% if (page.prev) { %>\r\n        <a class=\"page-btn\" href=\"<%- url_for(page.prev_link) %>\">← 上一页</a>\r\n      <% } else { %>\r\n        <span class=\"page-btn disabled\">← 上一页</span>\r\n      <% } %>\r\n      <span class=\"page-info\"><%- page.current %> / <%- page.total %></span>\r\n      <% if (page.next) { %>\r\n        <a class=\"page-btn\" href=\"<%- url_for(page.next_link) %>\">下一页 →</a>\r\n      <% } else { %>\r\n        <span class=\"page-btn disabled\">下一页 →</span>\r\n      <% } %>\r\n    </nav>\r\n  <% } else if (page.posts && page.posts.length) { %>\r\n    <p class=\"archive-total\">共 <%- page.posts.length %> 篇</p>\r\n  <% } %>\r\n</article>\r\n",
    "themes/cnblog/layout/category.ejs": "﻿<% if (page.type === 'categories' && !page.category) { %>\r\n  <article class=\"post-card archive-page\">\r\n    <h1 class=\"post-title\">分类</h1>\r\n    <% if (site.categories.length) { %>\r\n      <div class=\"cat-list\">\r\n        <% site.categories.sort('-length').each(function (cat) { %>\r\n          <%\r\n            var catFull = decodeURIComponent(cat.path || '')\r\n              .replace(/^categories\\//, '')\r\n              .replace(/\\/$/, '');\r\n            if (!catFull) catFull = cat.name;\r\n            var catDepth = catFull.split('/').length - 1;\r\n          %>\r\n          <a class=\"cat-item<%- catDepth > 0 ? ' cat-child' : '' %>\" href=\"<%- url_for(cat.path) %>\">\r\n            <span class=\"cat-name\"><%- catFull %></span>\r\n            <em class=\"cat-count\"><%- cat.length %></em>\r\n          </a>\r\n        <% }) %>\r\n      </div>\r\n    <% } else { %>\r\n      <p class=\"empty-tip\">还没有分类。</p>\r\n    <% } %>\r\n  </article>\r\n<% } else { %>\r\n  <%- partial('archive') %>\r\n<% } %>\r\n",
    "themes/cnblog/layout/index.ejs": "<% page.posts.each(function (post) { %>\r\n  <%- partial('_partial/post-card', { post: post }) %>\r\n<% }) %>\r\n\r\n<% if (page.total > 1) { %>\r\n  <nav class=\"pagination\">\r\n    <% if (page.prev) { %>\r\n      <a class=\"page-btn\" href=\"<%- url_for(page.prev_link) %>\">← 上一页</a>\r\n    <% } else { %>\r\n      <span class=\"page-btn disabled\">← 上一页</span>\r\n    <% } %>\r\n    <span class=\"page-info\"><%- page.current %> / <%- page.total %></span>\r\n    <% if (page.next) { %>\r\n      <a class=\"page-btn\" href=\"<%- url_for(page.next_link) %>\">下一页 →</a>\r\n    <% } else { %>\r\n      <span class=\"page-btn disabled\">下一页 →</span>\r\n    <% } %>\r\n  </nav>\r\n<% } %>\r\n",
    "themes/cnblog/layout/layout.ejs": "<%# 静态资源版本号：按天变化，避免浏览器缓存旧的 404 或旧样式 %>\r\n<% var assetV = new Date().toISOString().slice(0, 10).replace(/-/g, ''); %>\r\n<!DOCTYPE html>\r\n<html lang=\"<%- config.language || 'zh-CN' %>\">\r\n<head>\r\n  <%- partial('_partial/head', { assetV: assetV }) %>\r\n</head>\r\n<body class=\"skin-bluesky\">\r\n  <%- partial('_partial/header') %>\r\n\r\n  <div class=\"container\">\r\n    <main class=\"main-content\">\r\n      <%- body %>\r\n    </main>\r\n    <%- partial('_partial/sidebar') %>\r\n  </div>\r\n\r\n  <div class=\"sidebar-mask\" id=\"sidebarMask\"></div>\r\n\r\n  <%- partial('_partial/footer') %>\r\n  <script src=\"<%- url_for('/js/main.js') %>?v=<%- assetV %>\"></script>\r\n  <% if (config.views && config.views.enable && config.views.code) { %>\r\n  <%# 浏览量：GoatCounter 官方脚本。path 固定成 pathname，避免带 ?giscus= 之类的查询串 %>\r\n  <script>window.goatcounter = { path: location.pathname };</script>\r\n  <script data-goatcounter=\"https://<%= config.views.code %>.goatcounter.com/count\"\r\n          async src=\"https://gc.zgo.at/count.js\"></script>\r\n  <% } %>\r\n</body>\r\n</html>\r\n",
    "themes/cnblog/layout/page.ejs": "<article class=\"post-card post-full\">\r\n  <h1 class=\"post-title\"><%- page.title %></h1>\r\n  <div class=\"post-content\">\r\n    <%- page.content %>\r\n  </div>\r\n</article>\r\n",
    "themes/cnblog/layout/post.ejs": "<article class=\"post-card post-full\">\r\n  <h1 class=\"post-title\"><%- page.title %></h1>\r\n\r\n  <div class=\"post-meta\">\r\n    <span class=\"meta-item\"><%- date(page.date, 'YYYY-MM-DD HH:mm') %></span>\r\n    <% if (page.categories && page.categories.length) { %>\r\n      <% page.categories.each(function (cat) { %>\r\n        <a class=\"meta-item meta-cat\" href=\"<%- url_for(cat.path) %>\"><%- cat.name %></a>\r\n      <% }) %>\r\n    <% } %>\r\n    <%\r\n      // 浏览量（GoatCounter）：数字由 /js/main.js 拉取后填进来，拉不到就不显示\r\n      var _vs = config.views || {};\r\n    %>\r\n    <% if (_vs.enable && _vs.code) { %>\r\n      <span class=\"meta-item post-views\"\r\n        data-code=\"<%= _vs.code %>\"\r\n        data-label=\"<%= _vs.label || '阅读' %>\" hidden></span>\r\n    <% } %>\r\n  </div>\r\n\r\n  <div class=\"post-content\">\r\n    <% if (page.password) { %>\r\n      <%# 加密文章：摘要不加密，放在密码框上方让人知道大概内容 %>\r\n      <% var abstractHtml = page.abstract || page.excerpt; %>\r\n      <% if (abstractHtml) { %>\r\n        <div class=\"post-abstract\">\r\n          <span class=\"post-abstract-label\">摘要</span>\r\n          <div class=\"post-abstract-body\"><%- abstractHtml %></div>\r\n        </div>\r\n      <% } %>\r\n    <% } %>\r\n    <%- page.content %>\r\n  </div>\r\n\r\n  <% if (page.tags && page.tags.length) { %>\r\n    <div class=\"post-tags\">\r\n      <% page.tags.each(function (tag) { %>\r\n        <a href=\"<%- url_for(tag.path) %>\">#<%- tag.name %></a>\r\n      <% }) %>\r\n    </div>\r\n  <% } %>\r\n\r\n  <div class=\"post-nav\">\r\n    <% if (page.prev) { %>\r\n      <a class=\"post-nav-item prev\" href=\"<%- url_for(page.prev.path) %>\">\r\n        <span>上一篇</span><em><%- page.prev.title %></em>\r\n      </a>\r\n    <% } %>\r\n    <% if (page.next) { %>\r\n      <a class=\"post-nav-item next\" href=\"<%- url_for(page.next.path) %>\">\r\n        <span>下一篇</span><em><%- page.next.title %></em>\r\n      </a>\r\n    <% } %>\r\n  </div>\r\n\r\n  <%\r\n    /*\r\n     * 评论（giscus）：\r\n     * 配置写在**站点** _config.yml 的 comments 段，而不是主题配置——主题安装会整份\r\n     * 覆盖 themes/cnblog/_config.yml，repoId 那些手填的 ID 会被冲掉。\r\n     * 只有 enable 打开、且 repo / repoId / categoryId 都填了才渲染，\r\n     * 避免没配置时向 giscus.app 发一堆注定失败的请求。\r\n     * 加密文章（page.password）不挂评论区：讨论会泄露标题和摘要。\r\n     * 单篇想关评论，在 front-matter 写 comments: false。\r\n     */\r\n    var _cm = config.comments || {};\r\n    var _gc = _cm.giscus || {};\r\n    var _showComments = !!_cm.enable\r\n      && !!_gc.repo && !!_gc.repoId && !!_gc.categoryId\r\n      && page.comments !== false\r\n      && !page.password;\r\n  %>\r\n  <% if (_showComments) { %>\r\n    <section class=\"post-comments\" id=\"comments\"\r\n      data-repo=\"<%= _gc.repo %>\"\r\n      data-repo-id=\"<%= _gc.repoId %>\"\r\n      data-category=\"<%= _gc.category || '' %>\"\r\n      data-category-id=\"<%= _gc.categoryId %>\"\r\n      data-mapping=\"<%= _gc.mapping || 'pathname' %>\"\r\n      data-strict=\"<%= _gc.strict != null ? _gc.strict : 0 %>\"\r\n      data-reactions=\"<%= _gc.reactionsEnabled != null ? _gc.reactionsEnabled : 1 %>\"\r\n      data-emit-metadata=\"<%= _gc.emitMetadata != null ? _gc.emitMetadata : 0 %>\"\r\n      data-input-position=\"<%= _gc.inputPosition || 'top' %>\"\r\n      data-theme=\"<%= _gc.theme || 'auto' %>\"\r\n      data-lang=\"<%= _gc.lang || 'zh-CN' %>\"\r\n      data-loading=\"<%= _gc.loading || 'lazy' %>\">\r\n      <h2 class=\"comments-title\">评论</h2>\r\n      <div class=\"giscus\"></div>\r\n      <noscript>\r\n        <p class=\"comments-noscript\">评论由 giscus 提供（数据存在 GitHub Discussions），需要开启 JavaScript 才能加载。</p>\r\n      </noscript>\r\n    </section>\r\n  <% } %>\r\n</article>\r\n",
    "themes/cnblog/layout/tag.ejs": "<% if (page.type === 'tags' && !page.tag) { %>\r\n  <article class=\"post-card archive-page\">\r\n    <h1 class=\"post-title\">标签</h1>\r\n    <% if (site.tags.length) { %>\r\n      <div class=\"tag-cloud tag-cloud-page\">\r\n        <% site.tags.sort('-length').each(function (tag) { %>\r\n          <a href=\"<%- url_for(tag.path) %>\"><%- tag.name %><% if (tag.length) { %>(<%- tag.length %>)<% } %></a>\r\n        <% }) %>\r\n      </div>\r\n    <% } else { %>\r\n      <p class=\"empty-tip\">还没有标签。</p>\r\n    <% } %>\r\n  </article>\r\n<% } else { %>\r\n  <%- partial('archive') %>\r\n<% } %>\r\n",
    "themes/cnblog/layout/_partial/footer.ejs": "<footer class=\"footer\">\r\n  <p>\r\n    &copy; <%- (theme.footer && theme.footer.since) || '2026' %>–<%- new Date().getFullYear() %>\r\n    <%- (theme.footer && theme.footer.copyright) || theme.author %>\r\n  </p>\r\n  <p class=\"powered\">Powered by <a href=\"https://hexo.io\" target=\"_blank\" rel=\"noopener\">Hexo</a> · 主题参考 Cnblogs-Theme-SimpleMemory</p>\r\n</footer>\r\n",
    "themes/cnblog/layout/_partial/head.ejs": "﻿<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title><% if (page.title && !is_home()) { %><%- page.title %> - <% } %><%- config.title %></title>\r\n<meta name=\"description\" content=\"<%- config.description || '' %>\">\r\n<% if (page.keywords) { %><meta name=\"keywords\" content=\"<%- page.keywords %>\"><% } %>\r\n<link rel=\"stylesheet\" href=\"<%- url_for('/css/style.css') %>?v=<%- typeof assetV !== 'undefined' ? assetV : '1' %>\">",
    "themes/cnblog/layout/_partial/header.ejs": "<%\r\n  // 诗句来源：builtin（主题内置）/ api（一言接口）/ txt（仓库里的 motto.txt）\r\n  // 首屏先渲染一句保证不空白，main.js 再按来源替换。\r\n  var mottoSource = theme.mottoSource || 'builtin';\r\n  var mottoList = (theme.mottos || []).filter(function (m) { return m && m.text; });\r\n  var firstMotto = mottoSource === 'builtin' && mottoList.length ? mottoList[0] : null;\r\n  var mottoText = firstMotto ? firstMotto.text : theme.motto;\r\n  var mottoFrom = firstMotto ? firstMotto.from : theme.motto_from;\r\n%>\r\n<nav class=\"navbar\" id=\"navbar\">\r\n  <button class=\"menu-btn\" id=\"menuBtn\" type=\"button\" aria-label=\"菜单\">☰&nbsp;&nbsp;MENU</button>\r\n  <div class=\"navbar-links\" id=\"navLinks\">\r\n    <% Object.keys(theme.menu).forEach(function (name) { %>\r\n      <a href=\"<%- url_for(theme.menu[name]) %>\"<% if (decodeURI(page.path) === theme.menu[name]) { %> class=\"active\"<% } %>><%- name %></a>\r\n    <% }) %>\r\n  </div>\r\n  <button class=\"theme-btn\" id=\"themeBtn\" type=\"button\" title=\"切换深色模式\">☾</button>\r\n</nav>\r\n\r\n<header class=\"main-header<%- is_post() ? ' is-post' : '' %>\"\r\n        style=\"background-image:url('<%- url_for(theme.banner) %>')\">\r\n  <div class=\"header-inner\">\r\n    <h1 class=\"site-title\"><%- theme.author %></h1>\r\n    <p class=\"site-motto\"\r\n       data-source=\"<%- mottoSource %>\"\r\n       data-api=\"<%- theme.mottoApi || '' %>\"\r\n       data-txt=\"<%- url_for(theme.mottoTxt || '/motto.txt') %>\"\r\n       data-mottos=\"<%- encodeURIComponent(JSON.stringify(mottoList)) %>\"><%- mottoText %></p>\r\n    <p class=\"site-from\"><%- mottoFrom %></p>\r\n  </div>\r\n  <% if (is_home()) { %>\r\n    <a class=\"scroll-down\" href=\"#main\" aria-label=\"向下\">⌄</a>\r\n  <% } %>\r\n</header>\r\n",
    "themes/cnblog/layout/_partial/post-card.ejs": "<article class=\"post-card\">\r\n  <h2 class=\"post-title\">\r\n    <a href=\"<%- url_for(post.path) %>\"><%- post.title %></a>\r\n  </h2>\r\n\r\n  <div class=\"post-meta\">\r\n    <span class=\"meta-item\"><%- date(post.date, 'YYYY-MM-DD') %></span>\r\n    <% if (post.categories && post.categories.length) { %>\r\n      <% post.categories.each(function (cat) { %>\r\n        <a class=\"meta-item meta-cat\" href=\"<%- url_for(cat.path) %>\"><%- cat.name %></a>\r\n      <% }) %>\r\n    <% } %>\r\n  </div>\r\n\r\n  <% var summary = (post.excerpt || '').trim(); %>\r\n  <% if (summary) { %>\r\n    <div class=\"post-excerpt\">\r\n      <%- truncate(strip_html(summary), { length: 150 }) %>\r\n    </div>\r\n  <% } %>\r\n\r\n  <div class=\"post-footer\">\r\n    <a class=\"read-more\" href=\"<%- url_for(post.path) %>\">阅读全文 →</a>\r\n    <% if (post.tags && post.tags.length) { %>\r\n      <span class=\"post-tags-inline\">\r\n        <% post.tags.each(function (tag) { %>\r\n          <a href=\"<%- url_for(tag.path) %>\">#<%- tag.name %></a>\r\n        <% }) %>\r\n      </span>\r\n    <% } %>\r\n  </div>\r\n</article>\r\n",
    "themes/cnblog/layout/_partial/sidebar.ejs": "﻿<aside class=\"sidebar\">\r\n  <% if (is_post() && page.content && page.content.length > 500) { %>\r\n    <section class=\"widget toc-widget\">\r\n      <h3 class=\"widget-title\">目录</h3>\r\n      <div class=\"toc-wrap\"><%- toc(page.content, { list_number: false }) %></div>\r\n    </section>\r\n  <% } %>\r\n\r\n  <%\r\n    // 同分类合集：按首次发布时间升序，像博客园的系列文章\r\n    // Hexo 的 categories 是「层级」而不是并列：categories: [算法, 前端] 表示 算法/前端。\r\n    // 所以取 last() 拿到最末级分类，范围才精确（取 first() 会拿到父级的全部文章）。\r\n    if (is_post() && page.categories && page.categories.length) {\r\n      var catData = page.categories.last();\r\n      if (catData && catData.length > 1) {\r\n  %>\r\n    <section class=\"widget cat-series\">\r\n      <h3 class=\"widget-title\">\r\n        <a href=\"<%- url_for(catData.path) %>\"><%- catData.name %></a>\r\n        <span class=\"series-count\"><%- catData.length %> 篇</span>\r\n      </h3>\r\n      <ol class=\"series-list\">\r\n        <%\r\n          // 按文件夹里的自然顺序展示：先看 front-matter 的 order，再退回文件名\r\n          var seriesPosts = catData.posts.toArray().sort(function (a, b) {\r\n            var ao = a.order != null ? Number(a.order) : Infinity;\r\n            var bo = b.order != null ? Number(b.order) : Infinity;\r\n            if (ao !== bo) return ao - bo;\r\n            return String(a.source || \"\").localeCompare(String(b.source || \"\"), \"zh\");\r\n          });\r\n        %>\r\n        <% seriesPosts.forEach(function (p) { %>\r\n          <li<%- p.path === page.path ? ' class=\"active\"' : '' %>>\r\n            <a href=\"<%- url_for(p.path) %>\"><%- p.title %></a>\r\n          </li>\r\n        <% }) %>\r\n      </ol>\r\n    </section>\r\n  <%    }\r\n    }\r\n  %>\r\n\r\n  <% (theme.widgets || []).forEach(function (w) { %>\r\n\r\n    <% if (w === 'profile') { %>\r\n      <section class=\"widget profile\">\r\n        <% if (theme.avatar) { %>\r\n          <img class=\"avatar\" src=\"<%- theme.avatar %>\" alt=\"<%- theme.author %>\">\r\n        <% } else { %>\r\n          <div class=\"avatar avatar-text\"><%- (theme.author || 'A').trim().slice(0, 1).toUpperCase() %></div>\r\n        <% } %>\r\n        <h3 class=\"profile-name\"><%- theme.author %></h3>\r\n        <p class=\"profile-intro\"><%- theme.intro %></p>\r\n      </section>\r\n    <% } %>\r\n\r\n    <% if (w === 'stats') { %>\r\n      <section class=\"widget stats\">\r\n        <div class=\"stat\"><b><%- site.posts.length %></b><span>文章</span></div>\r\n        <div class=\"stat\"><b><%- site.categories.length %></b><span>分类</span></div>\r\n        <div class=\"stat\"><b><%- site.tags.length %></b><span>标签</span></div>\r\n      </section>\r\n    <% } %>\r\n\r\n    <% if (w === 'categories') { %>\r\n      <section class=\"widget\">\r\n        <h3 class=\"widget-title\">分类</h3>\r\n        <ul class=\"widget-list\">\r\n          <% site.categories.sort('-length').each(function (cat) { %>\r\n            <%\r\n              // 分类是层级结构，只显示末级名会和父级看起来并列，这里显示完整路径\r\n              var catFull = decodeURIComponent(cat.path || '')\r\n                .replace(/^categories\\//, '')\r\n                .replace(/\\/$/, '');\r\n              if (!catFull) catFull = cat.name;\r\n              var catDepth = catFull.split('/').length - 1;\r\n            %>\r\n            <li class=\"cat-item<%- catDepth > 0 ? ' cat-child' : '' %>\">\r\n              <a href=\"<%- url_for(cat.path) %>\">\r\n                <span class=\"cat-label\"><%- catFull %></span>\r\n                <span class=\"count\"><%- cat.length %></span>\r\n              </a>\r\n            </li>\r\n          <% }) %>\r\n        </ul>\r\n      </section>\r\n    <% } %>\r\n\r\n    <% if (w === 'tags') { %>\r\n      <section class=\"widget\">\r\n        <h3 class=\"widget-title\">标签</h3>\r\n        <div class=\"tag-cloud\">\r\n          <% site.tags.sort('-length').each(function (tag) { %>\r\n            <a href=\"<%- url_for(tag.path) %>\"><%- tag.name %><%- tag.length ? '(' + tag.length + ')' : '' %></a>\r\n          <% }) %>\r\n        </div>\r\n      </section>\r\n    <% } %>\r\n\r\n    <% if (w === 'recent') { %>\r\n      <section class=\"widget\">\r\n        <h3 class=\"widget-title\">最近文章</h3>\r\n        <ul class=\"widget-list recent\">\r\n          <% site.posts.sort('-date').limit(6).each(function (post) { %>\r\n            <li><a href=\"<%- url_for(post.path) %>\"><%- post.title %></a></li>\r\n          <% }) %>\r\n        </ul>\r\n      </section>\r\n    <% } %>\r\n\r\n  <% }) %>\r\n</aside>\r\n",
    "themes/cnblog/source/css/style.css": "﻿/* ========================================================\r\n   博客园风格主题（SimpleMemory 等效实现）\r\n   配色取自原站：主色 #5c8ec6，正文 #4a4a4a\r\n   ======================================================== */\r\n\r\n:root {\r\n  --primary: #5c8ec6;\r\n  --primary-dark: #4a7bb0;\r\n  --primary-light: #eaf1f9;\r\n  --text: #4a4a4a;\r\n  --text-light: #757575;\r\n  --text-dim: #9eabb3;\r\n  --bg: #f4f5f7;\r\n  --card: #ffffff;\r\n  --border: #e9e9e9;\r\n  --radius: 8px;\r\n  --shadow: 0 2px 12px rgba(0, 0, 0, .06);\r\n  --shadow-hover: 0 6px 22px rgba(0, 0, 0, .1);\r\n  --quote-border: #e2dfdf;\r\n  --quote-text: rgba(85, 85, 85, .72);\r\n  /* 代码块：浅色主题 */\r\n  --code-bg: #f6f8fa;\r\n  --code-text: #24292e;\r\n  --code-border: #eaecef;\r\n  --tok-keyword: #d73a49;\r\n  --tok-string: #032f62;\r\n  --tok-number: #005cc5;\r\n  --tok-comment: #6a737d;\r\n  --tok-function: #6f42c1;\r\n  --tok-type: #d73a49;\r\n  --tok-builtin: #005cc5;\r\n  --tok-literal: #005cc5;\r\n  --tok-meta: #6f42c1;\r\n  --tok-attr: #005cc5;\r\n  --tok-variable: #e36209;\r\n}\r\n\r\nbody.dark {\r\n  --text: #d6d9dd;\r\n  --text-light: #9aa1ad;\r\n  --text-dim: #6b7280;\r\n  --bg: #17191d;\r\n  --card: #1f2229;\r\n  --border: #2e323b;\r\n  --primary-light: #1e2a3a;\r\n  --shadow: 0 2px 12px rgba(0, 0, 0, .4);\r\n  --shadow-hover: 0 6px 22px rgba(0, 0, 0, .55);\r\n  --quote-border: #3a3f4b;\r\n  --quote-text: rgba(200, 205, 215, .75);\r\n  /* 代码块：深色主题 */\r\n  --code-bg: #282c34;\r\n  --code-text: #abb2bf;\r\n  --code-border: #3a3f4b;\r\n  --tok-keyword: #c678dd;\r\n  --tok-string: #98c379;\r\n  --tok-number: #d19a66;\r\n  --tok-comment: #5c6370;\r\n  --tok-function: #61afef;\r\n  --tok-type: #e5c07b;\r\n  --tok-builtin: #e5c07b;\r\n  --tok-literal: #56b6c2;\r\n  --tok-meta: #61afef;\r\n  --tok-attr: #d19a66;\r\n  --tok-variable: #e06c75;\r\n}\r\n\r\n* { box-sizing: border-box; }\r\n\r\nhtml { scroll-behavior: smooth; }\r\n\r\nbody {\r\n  margin: 0;\r\n  /* 与 Typora 一致：系统无衬线，标题与正文同族 */\r\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\",\r\n               \"PingFang SC\", Helvetica, Arial, sans-serif;\r\n  font-size: 15px;\r\n  line-height: 1.75;\r\n  color: var(--text);\r\n  background: var(--bg);\r\n  transition: background .25s, color .25s;\r\n}\r\n\r\n/* Typora 里标题不加粗、不分族，只靠字号区分；这里只加粗到 600 */\r\n.site-title,\r\n.post-title,\r\n.widget-title,\r\n.profile-name,\r\n.post-content h1,\r\n.post-content h2,\r\n.post-content h3,\r\n.post-content h4,\r\n.post-content h5,\r\n.post-content h6 {\r\n  font-family: inherit;\r\n}\r\n\r\na { color: var(--primary); text-decoration: none; transition: color .15s; }\r\na:hover { color: var(--primary-dark); }\r\n\r\nimg { max-width: 100%; height: auto; }\r\n\r\n/* ============ 顶部导航 ============ */\r\n.navbar {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  height: 56px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 16px;\r\n  padding: 0 24px;\r\n  background: transparent;\r\n  border-bottom: 1px solid transparent;\r\n  z-index: 100;\r\n  transition: background .25s, border-color .25s, box-shadow .25s;\r\n}\r\n\r\n.navbar.scrolled {\r\n  background: rgba(255, 255, 255, .92);\r\n  backdrop-filter: blur(10px);\r\n  -webkit-backdrop-filter: blur(10px);\r\n  border-bottom-color: rgba(0, 0, 0, .06);\r\n  box-shadow: 0 2px 10px rgba(0, 0, 0, .04);\r\n}\r\n\r\nbody.dark .navbar.scrolled {\r\n  background: rgba(31, 34, 41, .92);\r\n  border-bottom-color: rgba(255, 255, 255, .06);\r\n}\r\n\r\n.menu-btn,\r\n.theme-btn {\r\n  border: 1px solid rgba(255, 255, 255, .65);\r\n  background: rgba(255, 255, 255, .12);\r\n  color: #fff;\r\n  border-radius: 6px;\r\n  height: 32px;\r\n  padding: 0 12px;\r\n  font-size: 12px;\r\n  letter-spacing: .06em;\r\n  cursor: pointer;\r\n  transition: background .15s, border-color .15s, color .15s;\r\n}\r\n\r\n.navbar.scrolled .menu-btn,\r\n.navbar.scrolled .theme-btn {\r\n  border-color: var(--border);\r\n  background: transparent;\r\n  color: var(--text);\r\n}\r\n\r\n.menu-btn:hover,\r\n.theme-btn:hover {\r\n  background: rgba(255, 255, 255, .25);\r\n}\r\n\r\n.navbar.scrolled .menu-btn:hover,\r\n.navbar.scrolled .theme-btn:hover {\r\n  background: var(--primary-light);\r\n  border-color: var(--primary);\r\n}\r\n\r\n.theme-btn { margin-left: auto; width: 34px; padding: 0; font-size: 15px; }\r\n\r\n.navbar-links {\r\n  display: flex;\r\n  gap: 4px;\r\n  overflow-x: auto;\r\n}\r\n\r\n.navbar-links a {\r\n  padding: 6px 12px;\r\n  border-radius: 6px;\r\n  font-size: 14px;\r\n  color: rgba(255, 255, 255, .88);\r\n  white-space: nowrap;\r\n  transition: color .15s, background .15s;\r\n}\r\n\r\n.navbar.scrolled .navbar-links a { color: var(--text-light); }\r\n\r\n.navbar-links a:hover {\r\n  color: #fff;\r\n  background: rgba(255, 255, 255, .18);\r\n}\r\n\r\n.navbar.scrolled .navbar-links a:hover,\r\n.navbar.scrolled .navbar-links a.active {\r\n  color: var(--primary);\r\n  background: var(--primary-light);\r\n}\r\n\r\n/* ============ Banner ============ */\r\n.main-header {\r\n  position: relative;\r\n  height: 82vh;\r\n  min-height: 460px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  text-align: center;\r\n  color: #fff;\r\n  background-size: cover;\r\n  background-position: center;\r\n  background-repeat: no-repeat;\r\n}\r\n\r\n.main-header.is-post { height: 34vh; min-height: 240px; }\r\n\r\n.main-header::after {\r\n  content: \"\";\r\n  position: absolute;\r\n  inset: 0;\r\n  background: linear-gradient(180deg, rgba(0, 0, 0, .18), rgba(0, 0, 0, .42));\r\n}\r\n\r\n.header-inner {\r\n  position: relative;\r\n  z-index: 1;\r\n  padding: 0 20px;\r\n  animation: fadeUp .8s ease both;\r\n}\r\n\r\n.site-title {\r\n  margin: 0;\r\n  font-size: 3rem;\r\n  font-weight: 300;\r\n  letter-spacing: .1em;\r\n  text-shadow: 0 2px 16px rgba(0, 0, 0, .45);\r\n}\r\n\r\n.main-header.is-post .site-title { font-size: 2rem; }\r\n\r\n.site-motto {\r\n  margin: 14px 0 0;\r\n  font-size: 1.05rem;\r\n  opacity: .95;\r\n  text-shadow: 0 1px 8px rgba(0, 0, 0, .4);\r\n}\r\n\r\n.site-from {\r\n  margin: 6px 0 0;\r\n  font-size: .82rem;\r\n  opacity: .82;\r\n}\r\n\r\n.scroll-down {\r\n  position: absolute;\r\n  bottom: 26px;\r\n  left: 50%;\r\n  transform: translateX(-50%);\r\n  z-index: 1;\r\n  width: 38px;\r\n  height: 38px;\r\n  line-height: 34px;\r\n  border: 1px solid rgba(255, 255, 255, .7);\r\n  border-radius: 50%;\r\n  color: #fff;\r\n  font-size: 20px;\r\n  text-align: center;\r\n  animation: bounce 2s infinite;\r\n}\r\n.scroll-down:hover { background: rgba(255, 255, 255, .18); color: #fff; }\r\n\r\n@keyframes bounce {\r\n  0%, 100% { transform: translate(-50%, 0); }\r\n  50% { transform: translate(-50%, 8px); }\r\n}\r\n\r\n@keyframes fadeUp {\r\n  from { opacity: 0; transform: translateY(18px); }\r\n  to { opacity: 1; transform: translateY(0); }\r\n}\r\n\r\n/* ============ 布局 ============ */\r\n.container {\r\n  max-width: 1180px;\r\n  margin: 0 auto;\r\n  padding: 28px 20px 40px;\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) 300px;\r\n  gap: 24px;\r\n  align-items: start;\r\n  scroll-margin-top: 70px;\r\n}\r\n\r\n.main-content { min-width: 0; }\r\n\r\n/* ============ 文章卡片 ============ */\r\n.post-card {\r\n  background: var(--card);\r\n  border-radius: var(--radius);\r\n  padding: 26px 30px;\r\n  margin-bottom: 20px;\r\n  box-shadow: var(--shadow);\r\n  transition: transform .2s, box-shadow .2s;\r\n}\r\n\r\n.main-content > .post-card:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: var(--shadow-hover);\r\n}\r\n\r\n.post-title {\r\n  margin: 0 0 10px;\r\n  font-size: 1.42rem;\r\n  font-weight: 600;\r\n  line-height: 1.4;\r\n  color: var(--text);\r\n}\r\n\r\n.post-title a { color: inherit; }\r\n.post-title a:hover { color: var(--primary); }\r\n\r\n.post-meta {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: 14px;\r\n  font-size: 12.5px;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.meta-item { display: inline-flex; align-items: center; gap: 4px; }\r\n\r\n.meta-cat {\r\n  padding: 1px 9px;\r\n  border-radius: 999px;\r\n  background: var(--primary-light);\r\n  color: var(--primary);\r\n  font-size: 12px;\r\n}\r\n.meta-cat:hover { background: var(--primary); color: #fff; }\r\n\r\n/* 浏览量：数字由 JS 填，取不到时保持 hidden */\r\n.post-views { color: var(--text-dim); }\r\n.post-views[hidden] { display: none; }\r\n\r\n.post-excerpt {\r\n  margin: 16px 0 0;\r\n  color: var(--text-light);\r\n  font-size: 14.5px;\r\n  line-height: 1.85;\r\n  word-break: break-word;\r\n}\r\n\r\n.post-footer {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  margin-top: 18px;\r\n  padding-top: 14px;\r\n  border-top: 1px dashed var(--border);\r\n}\r\n\r\n.read-more { font-size: 13.5px; }\r\n\r\n.post-tags-inline {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 8px;\r\n  font-size: 12.5px;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.post-tags-inline a { color: var(--text-dim); }\r\n.post-tags-inline a:hover { color: var(--primary); }\r\n\r\n/* ============ 文章页正文 ============ */\r\n.post-full { padding: 38px 44px; }\r\n.post-full:hover { transform: none; box-shadow: var(--shadow); }\r\n\r\n.post-full .post-title { font-size: 1.9rem; }\r\n\r\n.post-content { margin-top: 22px; font-size: 15.5px; line-height: 1.9; }\r\n\r\n.post-content h1,\r\n.post-content h2,\r\n.post-content h3,\r\n.post-content h4,\r\n.post-content h5,\r\n.post-content h6 {\r\n  margin: 1.6em 0 .7em;\r\n  line-height: 1.4;\r\n  font-weight: 600;\r\n  color: var(--text);\r\n}\r\n\r\n/* 字号对齐原站：h2 28 / h3 24 / h4 20，否则 h4 会和正文同大 */\r\n.post-content h1 { font-size: 1.9rem; }\r\n.post-content h2 {\r\n  padding-bottom: .3em;\r\n  border-bottom: 1px solid var(--border);\r\n  font-size: 1.75rem;\r\n}\r\n.post-content h3 { font-size: 1.5rem; }\r\n.post-content h4 { font-size: 1.25rem; }\r\n.post-content h5 { font-size: 1.12rem; }\r\n.post-content h6 { font-size: 1rem; color: var(--text-light); }\r\n\r\n/* 文章里残留的 <font size=4> 会把后面整段正文放大，这里忽略 size，只保留颜色 */\r\n.post-content font[size] { font-size: inherit !important; }\r\n\r\n/* 与 Typora 一致：加粗只加粗，不改变字号与颜色 */\r\n.post-content strong,\r\n.post-content b { font-weight: 700; color: inherit; }\r\n\r\n.post-content p { margin: .9em 0; }\r\n\r\n.post-content a { border-bottom: 1px solid var(--primary-light); }\r\n.post-content a:hover { border-bottom-color: var(--primary); }\r\n\r\n.post-content img {\r\n  display: block;\r\n  margin: 1.2em auto;\r\n  border-radius: 6px;\r\n  box-shadow: var(--shadow);\r\n}\r\n\r\n.post-content blockquote {\r\n  margin: 1.2em 0;\r\n  padding: 6px 16px;\r\n  border-left: 4px solid var(--quote-border);\r\n  border-radius: 0 4px 4px 0;\r\n  background: transparent;\r\n  color: var(--quote-text);\r\n}\r\n\r\n/* Typora 风格的引用：无底色、细左边框、灰色文字 */\r\nbody.dark .post-content blockquote { color: var(--quote-text); }\r\n\r\n.post-content blockquote p { margin: .4em 0; }\r\n\r\n.post-content ul,\r\n.post-content ol { padding-left: 1.6em; }\r\n.post-content li { margin: .3em 0; }\r\n\r\n.post-content hr {\r\n  border: none;\r\n  border-top: 1px solid var(--border);\r\n  margin: 2em 0;\r\n}\r\n\r\n/* 代码：Hexo 输出的是 <figure class=\"highlight\"> + Pygments 类名 */\r\n.post-content figure.highlight {\r\n  margin: 1.2em 0;\r\n  padding: 0;\r\n  background: var(--code-bg);\r\n  border: 1px solid var(--code-border);\r\n  border-radius: 6px;\r\n  overflow: hidden;\r\n}\r\n\r\n.post-content figure.highlight table {\r\n  width: 100%;\r\n  margin: 0;\r\n  border-collapse: collapse;\r\n  display: block;\r\n  overflow-x: auto;\r\n}\r\n\r\n.post-content figure.highlight td {\r\n  border: none;\r\n  padding: 0;\r\n  vertical-align: top;\r\n}\r\n\r\n/* 去掉行号列 */\r\n.post-content figure.highlight .gutter,\r\n.post-content figure.highlight td.gutter { display: none; }\r\n\r\n.post-content figure.highlight pre {\r\n  margin: 0;\r\n  padding: 14px 18px;\r\n  background: transparent;\r\n  border: none;\r\n  border-radius: 0;\r\n  color: var(--code-text);\r\n  font-size: 14px;\r\n  line-height: 1.7;\r\n  font-family: Consolas, Monaco, \"Courier New\", monospace;\r\n  overflow-x: auto;\r\n}\r\n\r\n.post-content figure.highlight .line { color: var(--code-text); }\r\n\r\n.post-content pre {\r\n  margin: 1.2em 0;\r\n  padding: 14px 18px;\r\n  background: var(--code-bg);\r\n  color: var(--code-text);\r\n  border: 1px solid var(--code-border);\r\n  border-radius: 6px;\r\n  overflow-x: auto;\r\n  font-size: 14px;\r\n  line-height: 1.7;\r\n  font-family: Consolas, Monaco, \"Courier New\", monospace;\r\n}\r\n\r\n.post-content pre code {\r\n  padding: 0;\r\n  background: none;\r\n  color: inherit;\r\n  font-size: inherit;\r\n}\r\n\r\n.post-content code {\r\n  padding: .15em .4em;\r\n  background: var(--primary-light);\r\n  color: #c7254e;\r\n  border-radius: 4px;\r\n  font-size: .9em;\r\n  font-family: Consolas, Monaco, \"Courier New\", monospace;\r\n}\r\n\r\nbody.dark .post-content code { color: #e5a0a0; }\r\n\r\n/* 语法染色（随主题变量切换） */\r\n.post-content .highlight .keyword,\r\n.post-content .highlight .keyword .type { color: var(--tok-keyword); }\r\n.post-content .highlight .string,\r\n.post-content .highlight .string .subst { color: var(--tok-string); }\r\n.post-content .highlight .number,\r\n.post-content .highlight .literal { color: var(--tok-number); }\r\n.post-content .highlight .comment { color: var(--tok-comment); font-style: italic; }\r\n.post-content .highlight .function { color: var(--tok-function); }\r\n.post-content .highlight .type { color: var(--tok-type); }\r\n.post-content .highlight .built_in { color: var(--tok-builtin); }\r\n.post-content .highlight .meta,\r\n.post-content .highlight .meta-keyword,\r\n.post-content .highlight .preprocessor { color: var(--tok-meta); }\r\n.post-content .highlight .attr,\r\n.post-content .highlight .attribute { color: var(--tok-attr); }\r\n.post-content .highlight .variable,\r\n.post-content .highlight .template-variable { color: var(--tok-variable); }\r\n.post-content .highlight .title,\r\n.post-content .highlight .class .title { color: var(--tok-function); }\r\n.post-content .highlight .symbol,\r\n.post-content .highlight .bullet { color: var(--tok-literal); }\r\n\r\n/* 表格 */\r\n.post-content table {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  margin: 1.2em 0;\r\n  font-size: 14px;\r\n  display: block;\r\n  overflow-x: auto;\r\n}\r\n\r\n.post-content th,\r\n.post-content td {\r\n  border: 1px solid var(--border);\r\n  padding: 8px 12px;\r\n  text-align: left;\r\n}\r\n\r\n.post-content th { background: var(--primary-light); font-weight: 600; }\r\n\r\n/* KaTeX */\r\n.post-content .katex-display { overflow-x: auto; overflow-y: hidden; padding: 4px 0; }\r\n\r\n.post-tags {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 8px;\r\n  margin-top: 26px;\r\n  padding-top: 18px;\r\n  border-top: 1px dashed var(--border);\r\n}\r\n\r\n.post-tags a {\r\n  padding: 3px 11px;\r\n  font-size: 12.5px;\r\n  border-radius: 999px;\r\n  background: var(--primary-light);\r\n  color: var(--primary);\r\n}\r\n\r\n/* 上下篇 */\r\n.post-nav {\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 14px;\r\n  margin-top: 26px;\r\n}\r\n\r\n.post-nav-item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 4px;\r\n  padding: 12px 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  transition: border-color .15s, background .15s;\r\n}\r\n.post-nav-item:hover { border-color: var(--primary); background: var(--primary-light); }\r\n.post-nav-item span { font-size: 11.5px; color: var(--text-dim); }\r\n.post-nav-item em { font-style: normal; font-size: 13.5px; color: var(--text); }\r\n.post-nav-item.next { text-align: right; }\r\n\r\n/* ============ 评论（giscus） ============ */\r\n.post-comments {\r\n  margin-top: 38px;\r\n  padding-top: 24px;\r\n  border-top: 1px solid var(--border);\r\n}\r\n\r\n.comments-title {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  margin: 0 0 18px;\r\n  font-size: 1.05rem;\r\n  font-weight: 600;\r\n  color: var(--text);\r\n}\r\n\r\n.comments-title::before {\r\n  content: '';\r\n  flex: 0 0 auto;\r\n  width: 4px;\r\n  height: 17px;\r\n  border-radius: 2px;\r\n  background: var(--primary);\r\n}\r\n\r\n/* giscus 自己会往 .giscus 里塞 iframe 并加载它自己的 default.css */\r\n.giscus {\r\n  width: 100%;\r\n  min-height: 180px;\r\n}\r\n\r\n.giscus-frame {\r\n  width: 100%;\r\n  border: none;\r\n}\r\n\r\n/* 脚本还没把 iframe 插进来时的占位，避免评论区高度突然塌陷 */\r\n.giscus:empty::before {\r\n  content: '正在加载评论…';\r\n  display: block;\r\n  padding: 28px 0;\r\n  text-align: center;\r\n  font-size: 13px;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.comments-noscript {\r\n  margin: 0;\r\n  padding: 16px 18px;\r\n  font-size: 13px;\r\n  line-height: 1.7;\r\n  color: var(--text-light);\r\n  background: var(--primary-light);\r\n  border-radius: var(--radius);\r\n}\r\n\r\n/* ============ 归档 / 分类 / 标签 ============ */\r\n.archive-year {\r\n  margin: 1.6em 0 .6em;\r\n  font-size: 1.1rem;\r\n  color: var(--primary);\r\n}\r\n\r\n.archive-list {\r\n  list-style: none;\r\n  margin: 0 0 .4em;\r\n  padding: 0;\r\n}\r\n\r\n.archive-list li {\r\n  display: flex;\r\n  gap: 14px;\r\n  padding: 7px 0;\r\n  border-bottom: 1px dashed var(--border);\r\n}\r\n\r\n.archive-list time {\r\n  flex: 0 0 74px;\r\n  color: var(--text-dim);\r\n  font-size: 13px;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.archive-list a { color: var(--text); }\r\n.archive-list a:hover { color: var(--primary); }\r\n\r\n/* 分类索引页 */\r\n.cat-list {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\r\n  gap: 10px;\r\n  margin-top: 16px;\r\n}\r\n\r\n.cat-item {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 10px;\r\n  padding: 10px 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  color: var(--text);\r\n  transition: border-color .15s, background .15s, color .15s;\r\n}\r\n.cat-item:hover {\r\n  border-color: var(--primary);\r\n  background: var(--primary-light);\r\n  color: var(--primary);\r\n}\r\n.cat-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\r\n.cat-count {\r\n  font-style: normal;\r\n  font-size: 12px;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.tag-cloud-page { margin-top: 16px; gap: 10px; }\r\n.tag-cloud-page a { font-size: 13.5px; padding: 5px 14px; }\r\n\r\n.empty-tip { color: var(--text-dim); }\r\n\r\n/* ============ 分页 ============ */\r\n.pagination {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 14px;\r\n  margin: 26px 0 8px;\r\n}\r\n\r\n.page-btn {\r\n  padding: 7px 18px;\r\n  border-radius: 999px;\r\n  border: 1px solid var(--border);\r\n  background: var(--card);\r\n  color: var(--text-light);\r\n  font-size: 13.5px;\r\n}\r\n.page-btn:hover { border-color: var(--primary); color: var(--primary); }\r\n.page-btn.disabled { opacity: .45; cursor: not-allowed; }\r\n.page-info { font-size: 13px; color: var(--text-dim); }\r\n\r\n/* ============ 侧边栏 ============ */\r\n.sidebar {\r\n  position: sticky;\r\n  top: 76px;\r\n  /* 高度锁在视口内并内部滚动，否则内容比屏幕高时 sticky 会失效、目录跟着滚走 */\r\n  max-height: calc(100vh - 96px);\r\n  overflow-y: auto;\r\n  padding-right: 4px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 18px;\r\n  transition: opacity .25s;\r\n  /* 隐藏滚动条但保留滚动能力 */\r\n  scrollbar-width: none;\r\n  -ms-overflow-style: none;\r\n}\r\n\r\n.sidebar::-webkit-scrollbar { display: none; }\r\n\r\n/* 桌面端：MENU 把侧栏整体收起，主内容占满 */\r\nbody.sidebar-collapsed .sidebar { display: none; }\r\nbody.sidebar-collapsed .container { grid-template-columns: 1fr; }\r\n\r\n/* 移动端抽屉遮罩 */\r\n.sidebar-mask {\r\n  display: none;\r\n  position: fixed;\r\n  top: 56px;\r\n  left: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  background: rgba(0, 0, 0, .38);\r\n  z-index: 89;\r\n}\r\nbody.sidebar-open .sidebar-mask { display: block; }\r\n\r\n.widget {\r\n  background: var(--card);\r\n  border-radius: var(--radius);\r\n  padding: 20px 22px;\r\n  box-shadow: var(--shadow);\r\n}\r\n\r\n.widget-title {\r\n  margin: 0 0 14px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid var(--border);\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  color: var(--text);\r\n}\r\n\r\n.widget.profile { text-align: center; }\r\n\r\n.avatar {\r\n  width: 88px;\r\n  height: 88px;\r\n  border-radius: 50%;\r\n  object-fit: cover;\r\n  border: 3px solid var(--primary-light);\r\n}\r\n\r\n/* 没设置头像时用首字母占位 */\r\n.avatar-text {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 34px;\r\n  font-weight: 700;\r\n  color: #fff;\r\n  background: linear-gradient(135deg, var(--primary), #7ba7d4);\r\n}\r\n\r\n.profile-name { margin: 12px 0 6px; font-size: 15px; font-weight: 600; }\r\n.profile-intro { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--text-light); }\r\n\r\n.widget.stats {\r\n  display: flex;\r\n  justify-content: space-around;\r\n  text-align: center;\r\n  padding: 18px 12px;\r\n}\r\n\r\n.stat b { display: block; font-size: 1.35rem; color: var(--primary); font-weight: 600; }\r\n.stat span { font-size: 12px; color: var(--text-dim); }\r\n\r\n.widget-list { list-style: none; margin: 0; padding: 0; }\r\n\r\n.widget-list li {\r\n  padding: 0;\r\n  font-size: 13.5px;\r\n}\r\n\r\n/* 整行都能点：a 撑满 li，名称和计数用 flex 分开 */\r\n.widget-list li > a {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 8px;\r\n  padding: 7px 10px;\r\n  border-radius: 7px;\r\n  color: var(--text-light);\r\n  transition: background .15s, color .15s;\r\n}\r\n\r\n.widget-list li > a:hover {\r\n  background: var(--primary-light);\r\n  color: var(--primary);\r\n}\r\n\r\n.widget-list .cat-label {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.widget-list .count { font-size: 11.5px; color: var(--text-dim); }\r\n\r\n.widget-list.recent li { display: block; }\r\n.widget-list.recent a {\r\n  display: block;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.tag-cloud { display: flex; flex-wrap: wrap; gap: 7px; }\r\n\r\n.tag-cloud a {\r\n  padding: 3px 10px;\r\n  border-radius: 999px;\r\n  background: var(--primary-light);\r\n  color: var(--primary);\r\n  font-size: 12.5px;\r\n}\r\n.tag-cloud a:hover { background: var(--primary); color: #fff; }\r\n\r\n/* ============ 目录 ============ */\r\n.toc-widget { padding-bottom: 12px; }\r\n\r\n.toc-wrap {\r\n  max-height: 52vh;\r\n  overflow-y: auto;\r\n  font-size: 12.8px;\r\n  line-height: 1.7;\r\n}\r\n\r\n.toc-wrap .toc,\r\n.toc-wrap .toc-child {\r\n  list-style: none;\r\n  margin: 0;\r\n  padding: 0;\r\n}\r\n\r\n.toc-wrap .toc-child { padding-left: 12px; }\r\n\r\n.toc-wrap .toc-item { margin: 1px 0; }\r\n\r\n.toc-wrap .toc-link {\r\n  display: block;\r\n  padding: 2px 0 2px 9px;\r\n  border-left: 2px solid transparent;\r\n  color: var(--text-light);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  transition: color .15s, border-color .15s;\r\n}\r\n\r\n.toc-wrap .toc-link:hover { color: var(--primary); }\r\n\r\n.toc-wrap .toc-link.active {\r\n  color: var(--primary);\r\n  border-left-color: var(--primary);\r\n  font-weight: 600;\r\n}\r\n\r\n.toc-wrap .toc-level-1 > .toc-link { font-weight: 600; }\r\n.toc-wrap .toc-level-4 > .toc-link,\r\n.toc-wrap .toc-level-5 > .toc-link { color: var(--text-dim); }\r\n\r\n/* ============ 页脚 ============ */\r\n.footer {\r\n  padding: 30px 20px 40px;\r\n  text-align: center;\r\n  font-size: 12.5px;\r\n  color: var(--text-dim);\r\n  border-top: 1px solid var(--border);\r\n  background: var(--card);\r\n}\r\n\r\n.footer p { margin: 4px 0; }\r\n.footer a { color: var(--text-light); }\r\n.footer a:hover { color: var(--primary); }\r\n\r\n/* ============ 响应式 ============ */\r\n@media (max-width: 960px) {\r\n  .container {\r\n    grid-template-columns: 1fr;\r\n    padding: 20px 14px 30px;\r\n  }\r\n\r\n  /* 侧边栏变成左侧抽屉，和 MENU 按钮同侧，默认收在屏幕外 */\r\n  .sidebar {\r\n    position: fixed;\r\n    top: 56px;\r\n    left: 0;\r\n    right: auto;\r\n    bottom: 0;\r\n    width: 310px;\r\n    max-width: 86vw;\r\n    padding: 14px;\r\n    overflow-y: auto;\r\n    background: var(--bg);\r\n    box-shadow: 6px 0 24px rgba(0, 0, 0, .18);\r\n    transform: translateX(-105%);\r\n    transition: transform .3s ease;\r\n    z-index: 90;\r\n    display: flex;\r\n  }\r\n  body.sidebar-open .sidebar { transform: translateX(0); }\r\n  /* 移动端由 sidebar-open 控制，忽略 collapsed 的隐藏 */\r\n  body.sidebar-collapsed .sidebar { display: flex; }\r\n  body.sidebar-collapsed .container { grid-template-columns: 1fr; }\r\n\r\n  .site-title { font-size: 2rem; }\r\n  .main-header { height: 60vh; min-height: 340px; }\r\n  .post-full { padding: 26px 20px; }\r\n  .post-card { padding: 20px; }\r\n  .post-nav { grid-template-columns: 1fr; }\r\n  .navbar { padding: 0 12px; }\r\n}\r\n\r\n@media (max-width: 560px) {\r\n  .site-title { font-size: 1.65rem; }\r\n  .navbar-links a { padding: 6px 8px; font-size: 13px; }\r\n  .post-full { padding: 22px 16px; }\r\n  .post-card { padding: 16px; }\r\n  .post-meta { gap: 10px; font-size: 12px; }\r\n}\r\n/* ============ 加密文章的密码框（hexo-blog-encrypt）============ */\r\n/* 插件默认是「浮动标签」结构，label 绝对定位贴在 input 上方，\r\n   这里把 label 拉回文档流当作说明文字，避免和 input 重叠。 */\r\n#hexo-blog-encrypt.hbe-container {\r\n  margin: 1.8em 0;\r\n  padding: 26px 20px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  background: var(--card);\r\n  text-align: center;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-content,\r\n#hexo-blog-encrypt .hbe-form {\r\n  display: block;\r\n  margin: 0;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-input {\r\n  position: relative;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: stretch;\r\n  width: min(320px, 100%);\r\n  margin: 0 auto;\r\n  background: none;\r\n  box-shadow: none;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-input-label {\r\n  order: -1;\r\n  background: none !important;\r\n  box-shadow: none !important;\r\n  position: static !important;\r\n  display: block !important;\r\n  margin: 0 0 6px !important;\r\n  padding: 0 !important;\r\n  transform: none !important;\r\n  font-size: 13px !important;\r\n  line-height: 1.5 !important;\r\n  color: var(--text-light) !important;\r\n  text-align: left !important;\r\n  pointer-events: none;\r\n  white-space: normal;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-input-label-content {\r\n  position: static !important;\r\n  border: none !important;\r\n  box-shadow: none !important;\r\n  display: block !important;\r\n  padding: 0 !important;\r\n  transform: none !important;\r\n  font-size: inherit !important;\r\n  color: inherit !important;\r\n  background: none !important;\r\n}\r\n\r\n/* 插件用伪元素画了输入框的装饰块，这里一并去掉 */\r\n#hexo-blog-encrypt .hbe-input-label::before,\r\n#hexo-blog-encrypt .hbe-input-label::after,\r\n#hexo-blog-encrypt .hbe-input-label-content::before,\r\n#hexo-blog-encrypt .hbe-input-label-content::after,\r\n#hexo-blog-encrypt .hbe-input::before,\r\n#hexo-blog-encrypt .hbe-input::after {\r\n  display: none !important;\r\n  content: none !important;\r\n  background: none !important;\r\n  width: 0 !important;\r\n  height: 0 !important;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-input-field {\r\n  width: 100% !important;\r\n  height: auto !important;\r\n  margin: 0 !important;\r\n  padding: 9px 12px !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius) !important;\r\n  background: var(--bg) !important;\r\n  color: var(--text) !important;\r\n  font-size: 14px !important;\r\n  line-height: 1.5 !important;\r\n  box-shadow: none !important;\r\n  outline: none;\r\n  transition: border-color .15s;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-input-field:focus { border-color: var(--primary) !important; }\r\n\r\n#hexo-blog-encrypt .hbe-button {\r\n  width: auto !important;\r\n  margin-top: 14px !important;\r\n  padding: 8px 24px !important;\r\n  border: none !important;\r\n  border-radius: var(--radius) !important;\r\n  background: var(--primary) !important;\r\n  color: #fff !important;\r\n  font-size: 14px !important;\r\n  cursor: pointer;\r\n  transition: opacity .15s;\r\n}\r\n\r\n#hexo-blog-encrypt .hbe-button:hover { opacity: .88; }\r\n#hexo-blog-encrypt .hbe-button:disabled { opacity: .6; cursor: default; }\r\n\r\n#hexo-blog-encrypt .hbe-error {\r\n  min-height: 1em;\r\n  margin-top: 10px;\r\n  color: #c0392b;\r\n  font-size: 13px;\r\n}\r\n\r\nbody.dark #hexo-blog-encrypt .hbe-error { color: #e57373; }\r\n/* ============ 加密文章上方的摘要 ============ */\r\n.post-abstract {\r\n  margin: 0 0 1.6em;\r\n  padding: 14px 18px;\r\n  border: 1px solid var(--border);\r\n  border-left: 3px solid var(--primary);\r\n  border-radius: var(--radius);\r\n  background: var(--panel-2, var(--primary-light));\r\n}\r\n\r\n.post-abstract-label {\r\n  display: inline-block;\r\n  margin-bottom: 6px;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  letter-spacing: .5px;\r\n  color: var(--primary);\r\n}\r\n\r\n.post-abstract-body {\r\n  font-size: 14px;\r\n  line-height: 1.75;\r\n  color: var(--text-light);\r\n}\r\n\r\n.post-abstract-body p { margin: 0; }\r\n.post-abstract-body img { display: none; }\r\n/* ============ 归档 / 分类 / 标签列表 ============ */\r\n.archive-page { padding-bottom: 10px; }\r\n\r\n.archive-year {\r\n  margin: 1.5em 0 .5em;\r\n  padding-bottom: .3em;\r\n  border-bottom: 1px solid var(--border);\r\n  font-size: 1.05rem;\r\n  font-weight: 600;\r\n  color: var(--primary);\r\n}\r\n.archive-year:first-of-type { margin-top: .8em; }\r\n\r\n.archive-item {\r\n  padding: .5em 0;\r\n  border-bottom: 1px dashed var(--border);\r\n}\r\n.archive-item:last-of-type { border-bottom: none; }\r\n\r\n.archive-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 10px;\r\n}\r\n\r\n.archive-date {\r\n  flex: 0 0 auto;\r\n  font-size: 12.5px;\r\n  color: var(--text-dim);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.archive-title {\r\n  font-size: 15px;\r\n  color: var(--text);\r\n  transition: color .15s;\r\n}\r\n.archive-title:hover { color: var(--primary); }\r\n\r\n/* 标题下面的摘要，小一号灰字 */\r\n.archive-excerpt {\r\n  margin: 3px 0 0 62px;\r\n  font-size: 12.8px;\r\n  line-height: 1.65;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.archive-total {\r\n  margin: 1.4em 0 0;\r\n  font-size: 12.5px;\r\n  color: var(--text-dim);\r\n  text-align: center;\r\n}\r\n\r\n@media (max-width: 560px) {\r\n  .archive-excerpt { margin-left: 0; }\r\n}\r\n/* ============ 同分类合集（文章页侧栏）============ */\r\n.cat-series .widget-title {\r\n  display: flex;\r\n  align-items: baseline;\r\n  justify-content: space-between;\r\n  gap: 8px;\r\n}\r\n.cat-series .widget-title a { color: inherit; }\r\n\r\n.series-count {\r\n  font-size: 11.5px;\r\n  font-weight: 400;\r\n  color: var(--text-dim);\r\n}\r\n\r\n.series-list {\r\n  margin: 0;\r\n  padding: 0 0 0 1.5em;\r\n  font-size: 13px;\r\n  line-height: 1.75;\r\n  color: var(--text-light);\r\n  max-height: 40vh;\r\n  overflow-y: auto;\r\n}\r\n\r\n.series-list li { margin: 2px 0; }\r\n\r\n.series-list a {\r\n  color: var(--text-light);\r\n  transition: color .15s;\r\n}\r\n.series-list a:hover { color: var(--primary); }\r\n\r\n.series-list li.active {\r\n  font-weight: 600;\r\n}\r\n.series-list li.active a {\r\n  color: var(--primary);\r\n}\r\n\r\n.series-list::-webkit-scrollbar { width: 5px; }\r\n.series-list::-webkit-scrollbar-thumb {\r\n  background: var(--border);\r\n  border-radius: 3px;\r\n}\r\n/* 分类索引页：子分类缩进 */\r\n.cat-list .cat-item.cat-child {\r\n  padding-left: 30px;\r\n  position: relative;\r\n}\r\n.cat-list .cat-item.cat-child::before {\r\n  content: \"└\";\r\n  position: absolute;\r\n  left: 12px;\r\n  color: var(--border);\r\n}\r\n/* 目录 / 合集 / 分类索引：隐藏滚动条，保留滚动 */\r\n.toc-wrap,\r\n.series-list {\r\n  scrollbar-width: none;\r\n  -ms-overflow-style: none;\r\n}\r\n.toc-wrap::-webkit-scrollbar,\r\n.series-list::-webkit-scrollbar { display: none; }\r\n\r\n/* 侧栏分类项：覆盖索引页的 .cat-item 样式（那里是 flex 卡片），否则 a 会被当 flex item 收缩 */\r\n.widget-list .cat-item {\r\n  display: block;\r\n  padding: 0;\r\n  border: none;\r\n  border-radius: 0;\r\n  background: transparent;\r\n}\r\n.widget-list li > a { width: 100%; box-sizing: border-box; }\r\n.widget-list li.cat-child > a { padding-left: 22px; position: relative; }\r\n.widget-list li.cat-child > a::before {\r\n  content: \"└\";\r\n  position: absolute;\r\n  left: 8px;\r\n  color: var(--border);\r\n}\r\n/* ============ 任务列表 ============ */\r\n.post-content .contains-task-list,\r\n.post-content .contains-task-list > li,\r\n.post-content li:has(> input[type=\"checkbox\"]) {\r\n  list-style: none;\r\n}\r\n.post-content .contains-task-list,\r\n.post-content ul:has(> li > input[type=\"checkbox\"]) {\r\n  padding-left: 1.2em;\r\n}\r\n.post-content .task-list-item {\r\n  list-style: none;\r\n  margin: .3em 0;\r\n}\r\n.post-content .task-list-item-checkbox {\r\n  margin-right: 6px;\r\n  width: 13px;\r\n  height: 13px;\r\n  vertical-align: middle;\r\n  accent-color: var(--primary);\r\n}\r\n/* 列表项内的标题（- [ ] ##### xxx）：紧凑显示，像 Typora */\r\n.post-content li > h1, .post-content li > h2, .post-content li > h3,\r\n.post-content li > h4, .post-content li > h5, .post-content li > h6 {\r\n  display: inline;\r\n  margin: 0;\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  color: var(--primary);\r\n}\r\n.post-content li > h1 a, .post-content li > h2 a, .post-content li > h3 a,\r\n.post-content li > h4 a, .post-content li > h5 a, .post-content li > h6 a {\r\n  color: inherit;\r\n}\r\n",
    "themes/cnblog/source/js/main.js": "﻿(function () {\r\n  'use strict';\r\n\r\n  // 诗句：按来源取（内置 / 一言 API / 仓库 motto.txt）\r\n  var mottoEl = document.querySelector('.site-motto');\r\n  var fromEl = document.querySelector('.site-from');\r\n  if (mottoEl) {\r\n    var source = mottoEl.dataset.source || 'builtin';\r\n\r\n    var applyMotto = function (text, from) {\r\n      if (!text) return;\r\n      mottoEl.textContent = text;\r\n      if (fromEl && from) fromEl.textContent = from;\r\n    };\r\n\r\n    if (source === 'api') {\r\n      var api = mottoEl.dataset.api;\r\n      if (api) {\r\n        fetch(api, { mode: 'cors' })\r\n          .then(function (r) { return r.json(); })\r\n          .then(function (d) {\r\n            var text = d.hitokoto || d.text || d.motto || '';\r\n            var from = d.from || d.from_who || d.source || '';\r\n            applyMotto(text, from);\r\n          })\r\n          .catch(function () { /* 接口挂了就保留首屏那句 */ });\r\n      }\r\n    } else if (source === 'txt') {\r\n      fetch(mottoEl.dataset.txt || '/motto.txt')\r\n        .then(function (r) { return r.text(); })\r\n        .then(function (txt) {\r\n          var lines = txt.split(/\\r?\\n/).map(function (s) { return s.trim(); }).filter(Boolean);\r\n          if (!lines.length) return;\r\n          var pick = lines[Math.floor(Math.random() * lines.length)];\r\n          // 格式：句子 —— 出处（破折号后可省，-- 与单个 — 也认）\r\n          var m = pick.match(/^(.*?)\\s*(?:——|—|--)\\s*(.+)$/);\r\n          if (m) applyMotto(m[1].trim(), m[2].trim());\r\n          else applyMotto(pick, '');\r\n        })\r\n        .catch(function () { /* 文件缺失保留首屏那句 */ });\r\n    } else {\r\n      var list = [];\r\n      try {\r\n        list = JSON.parse(decodeURIComponent(mottoEl.dataset.mottos || '[]'));\r\n      } catch (e) { list = []; }\r\n      if (list.length > 1) {\r\n        var pick = list[Math.floor(Math.random() * list.length)];\r\n        applyMotto(pick.text, pick.from);\r\n      }\r\n    }\r\n  }\r\n\r\n  // 滚动后导航栏由透明变实底\r\n  var navbar = document.getElementById('navbar');\r\n  if (navbar) {\r\n    var onScroll = function () {\r\n      navbar.classList.toggle('scrolled', window.scrollY > 60);\r\n    };\r\n    window.addEventListener('scroll', onScroll, { passive: true });\r\n    onScroll();\r\n  }\r\n\r\n  // MENU：桌面收起/展开侧栏，移动端滑出抽屉\r\n  var menuBtn = document.getElementById('menuBtn');\r\n  var sidebarMask = document.getElementById('sidebarMask');\r\n  function toggleSidebar() {\r\n    if (window.innerWidth <= 960) {\r\n      document.body.classList.toggle('sidebar-open');\r\n    } else {\r\n      document.body.classList.toggle('sidebar-collapsed');\r\n    }\r\n  }\r\n  function closeSidebar() {\r\n    document.body.classList.remove('sidebar-open');\r\n  }\r\n  if (menuBtn) menuBtn.addEventListener('click', toggleSidebar);\r\n  if (sidebarMask) sidebarMask.addEventListener('click', closeSidebar);\r\n  document.addEventListener('keydown', function (e) {\r\n    if (e.key === 'Escape') closeSidebar();\r\n  });\r\n\r\n  // 评论（giscus）：文章页才有 .post-comments 容器，其他页面不会加载它的脚本\r\n  var giscusSection = document.querySelector('.post-comments');\r\n\r\n  // theme 配置里的 auto = 跟随本站的深浅色开关；其他值原样交给 giscus\r\n  function giscusThemeName() {\r\n    var mode = (giscusSection && giscusSection.dataset.theme) || 'auto';\r\n    if (mode !== 'auto') return mode;\r\n    return document.body.classList.contains('dark') ? 'dark' : 'light';\r\n  }\r\n\r\n  // giscus 的 iframe 是 giscus.app 的独立文档（跨域），换主题只能 postMessage\r\n  function syncGiscusTheme() {\r\n    if (!giscusSection) return;\r\n    var frame = giscusSection.querySelector('iframe.giscus-frame');\r\n    if (!frame || !frame.contentWindow) return;\r\n    frame.contentWindow.postMessage(\r\n      { giscus: { setConfig: { theme: giscusThemeName() } } },\r\n      'https://giscus.app'\r\n    );\r\n  }\r\n\r\n  function mountGiscus() {\r\n    if (!giscusSection) return;\r\n    var box = giscusSection.querySelector('.giscus');\r\n    if (!box || box.dataset.mounted) return;\r\n    box.dataset.mounted = '1';\r\n\r\n    var d = giscusSection.dataset;\r\n    var attrs = {\r\n      repo: d.repo,\r\n      'repo-id': d.repoId,\r\n      category: d.category || '',\r\n      'category-id': d.categoryId,\r\n      mapping: d.mapping || 'pathname',\r\n      strict: d.strict || '0',\r\n      'reactions-enabled': d.reactions || '1',\r\n      'emit-metadata': d.emitMetadata || '0',\r\n      'input-position': d.inputPosition || 'top',\r\n      theme: giscusThemeName(),\r\n      lang: d.lang || 'zh-CN',\r\n      loading: d.loading || 'lazy',\r\n    };\r\n\r\n    var script = document.createElement('script');\r\n    script.src = 'https://giscus.app/client.js';\r\n    script.async = true;\r\n    script.crossOrigin = 'anonymous';\r\n    Object.keys(attrs).forEach(function (k) {\r\n      script.setAttribute('data-' + k, attrs[k]);\r\n    });\r\n\r\n    // giscus 会把 iframe 塞进页面里的 .giscus 容器（并清空其子节点），\r\n    // 所以脚本本身挂到 body，别放进容器里。\r\n    document.body.appendChild(script);\r\n\r\n    // iframe 由 giscus 动态插入，出现后再同步一次主题：\r\n    // 首次加载时用户可能已经点过深色开关，而脚本里的 data-theme 是加载那一刻的值。\r\n    if (window.MutationObserver) {\r\n      var obs = new MutationObserver(function () {\r\n        var frame = box.querySelector('iframe.giscus-frame');\r\n        if (!frame) return;\r\n        obs.disconnect();\r\n        frame.addEventListener('load', syncGiscusTheme);\r\n      });\r\n      obs.observe(box, { childList: true });\r\n    }\r\n  }\r\n\r\n  // 深色模式\r\n  var themeBtn = document.getElementById('themeBtn');\r\n  var STORAGE_KEY = 'cnblog-theme';\r\n\r\n  function applyTheme(dark) {\r\n    document.body.classList.toggle('dark', dark);\r\n    if (themeBtn) themeBtn.textContent = dark ? '☀' : '☾';\r\n    syncGiscusTheme();\r\n  }\r\n\r\n  var saved = localStorage.getItem(STORAGE_KEY);\r\n  if (saved === 'dark') applyTheme(true);\r\n  else if (saved === 'light') applyTheme(false);\r\n  else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) applyTheme(true);\r\n\r\n  if (themeBtn) {\r\n    themeBtn.addEventListener('click', function () {\r\n      var dark = !document.body.classList.contains('dark');\r\n      applyTheme(dark);\r\n      localStorage.setItem(STORAGE_KEY, dark ? 'dark' : 'light');\r\n    });\r\n  }\r\n\r\n  // 深浅色确定之后再挂 giscus，脚本里的 data-theme 才是首屏该有的值\r\n  mountGiscus();\r\n\r\n  // 浏览量（GoatCounter）：读 count.json 填数字。\r\n  // 404 = 这个路径还没被统计过，按 0 显示；403 = 站点没开公开计数，保持隐藏。\r\n  var viewsEl = document.querySelector('.post-views');\r\n  if (viewsEl && viewsEl.dataset.code) {\r\n    fetch('https://' + viewsEl.dataset.code + '.goatcounter.com/counter/'\r\n      + encodeURIComponent(location.pathname) + '.json',\r\n      { headers: { Accept: 'application/json' } })\r\n      .then(function (r) {\r\n        if (r.status === 404) return { count: '0' };\r\n        return r.ok ? r.json() : null;\r\n      })\r\n      .then(function (d) {\r\n        if (!d || d.count == null) return;\r\n        viewsEl.textContent = (viewsEl.dataset.label || '阅读') + ' ' + d.count;\r\n        viewsEl.hidden = false;\r\n      })\r\n      .catch(function () { /* 忽略：广告插件或网络问题 */ });\r\n  }\r\n\r\n  // 目录滚动高亮\r\n  var tocLinks = Array.prototype.slice.call(document.querySelectorAll('.toc-wrap .toc-link'));\r\n  if (tocLinks.length) {\r\n    var headingMap = {};\r\n    tocLinks.forEach(function (link) {\r\n      var id = decodeURIComponent((link.getAttribute('href') || '').replace(/^#/, ''));\r\n      var el = document.getElementById(id);\r\n      if (el) headingMap[id] = link;\r\n    });\r\n\r\n    var current = null;\r\n    function updateActive() {\r\n      var passed = null;\r\n      Object.keys(headingMap).forEach(function (id) {\r\n        var el = document.getElementById(id);\r\n        if (el && el.getBoundingClientRect().top <= 120) passed = id;\r\n      });\r\n      var next = passed ? headingMap[passed] : null;\r\n      if (next === current) return;\r\n      if (current) current.classList.remove('active');\r\n      if (next) {\r\n        next.classList.add('active');\r\n        // 让高亮项在目录里保持可见\r\n        var wrap = next.closest('.toc-wrap');\r\n        if (wrap) {\r\n          var top = next.offsetTop - wrap.clientHeight / 2;\r\n          if (Math.abs(wrap.scrollTop - top) > wrap.clientHeight / 2) wrap.scrollTop = Math.max(0, top);\r\n        }\r\n      }\r\n      current = next;\r\n    }\r\n\r\n    window.addEventListener('scroll', updateActive, { passive: true });\r\n    updateActive();\r\n\r\n    // 点击平滑滚动，抵消固定导航栏的高度\r\n    tocLinks.forEach(function (link) {\r\n      link.addEventListener('click', function (e) {\r\n        var id = decodeURIComponent((link.getAttribute('href') || '').replace(/^#/, ''));\r\n        var el = document.getElementById(id);\r\n        if (!el) return;\r\n        e.preventDefault();\r\n        window.scrollTo({ top: el.getBoundingClientRect().top + window.scrollY - 80, behavior: 'smooth' });\r\n        history.replaceState(null, '', '#' + id);\r\n      });\r\n    });\r\n  }\r\n})();\r\n",
    "themes/cnblog/_config.yml": "﻿# 博客园风格主题（SimpleMemory 等效实现）\r\n# 视觉参考 Cnblogs-Theme-SimpleMemory，纯静态实现，不依赖其 JS\r\n\r\n# 站点主人（显示在 banner 上）\r\nauthor: FAKUMARER\r\n\r\n# banner 上的格言（首屏先显示 motto，再由 JS 按 mottoSource 替换）\r\n#\r\n# mottoSource:\r\n#   builtin → 从下面的 mottos 列表随机抽\r\n#   api     → 每次访问请求 mottoApi（一言接口）\r\n#   txt     → 从仓库里的 mottoTxt 随机读一行\r\nmottoSource: builtin\r\nmotto: 星垂平野阔，月涌大江流。\r\nmotto_from: 《旅夜书怀》· 唐代 · 杜甫\r\n\r\n# 一言接口（mottoSource: api 时使用）\r\n# 默认 Hitokoto 的诗词分类，返回 JSON：{ hitokoto, from, from_who, ... }\r\n# 想换分类就改 c 参数：c=i 诗词 / c=d 文学 / c=k 哲学 ...\r\nmottoApi: https://v1.hitokoto.cn/?c=i&encode=json\r\n\r\n# 诗句文件（mottoSource: txt 时使用）\r\n# 一行一句，可以用 | 分隔出处，例如：长风破浪会有时，直挂云帆济沧海。|《行路难》· 李白\r\nmottoTxt: /motto.txt\r\n\r\n# 内置诗句库（mottoSource: builtin 时生效）\r\nmottos:\r\n  - text: 星垂平野阔，月涌大江流。\r\n    from: 《旅夜书怀》· 唐代 · 杜甫\r\n  - text: 长风破浪会有时，直挂云帆济沧海。\r\n    from: 《行路难·其一》· 唐代 · 李白\r\n  - text: 会当凌绝顶，一览众山小。\r\n    from: 《望岳》· 唐代 · 杜甫\r\n  - text: 千磨万击还坚劲，任尔东西南北风。\r\n    from: 《竹石》· 清代 · 郑燮\r\n  - text: 沉舟侧畔千帆过，病树前头万木春。\r\n    from: 《酬乐天扬州初逢席上见赠》· 唐代 · 刘禹锡\r\n  - text: 海内存知己，天涯若比邻。\r\n    from: 《送杜少府之任蜀州》· 唐代 · 王勃\r\n  - text: 落霞与孤鹜齐飞，秋水共长天一色。\r\n    from: 《滕王阁序》· 唐代 · 王勃\r\n  - text: 山重水复疑无路，柳暗花明又一村。\r\n    from: 《游山西村》· 宋代 · 陆游\r\n  - text: 不经一番寒彻骨，怎得梅花扑鼻香。\r\n    from: 《上堂开示颂》· 唐代 · 黄檗禅师\r\n  - text: 路漫漫其修远兮，吾将上下而求索。\r\n    from: 《离骚》· 战国 · 屈原\r\n  - text: 大鹏一日同风起，扶摇直上九万里。\r\n    from: 《上李邕》· 唐代 · 李白\r\n  - text: 莫愁前路无知己，天下谁人不识君。\r\n    from: 《别董大》· 唐代 · 高适\r\n  - text: 生当作人杰，死亦为鬼雄。\r\n    from: 《夏日绝句》· 宋代 · 李清照\r\n  - text: 天行健，君子以自强不息。\r\n    from: 《周易·乾卦》\r\n  - text: 博观而约取，厚积而薄发。\r\n    from: 《稼说送张琥》· 宋代 · 苏轼\r\n  - text: 纸上得来终觉浅，绝知此事要躬行。\r\n    from: 《冬夜读书示子聿》· 宋代 · 陆游\r\n  - text: 问渠那得清如许？为有源头活水来。\r\n    from: 《观书有感》· 宋代 · 朱熹\r\n  - text: 衣带渐宽终不悔，为伊消得人憔悴。\r\n    from: 《蝶恋花》· 宋代 · 柳永\r\n  - text: 众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。\r\n    from: 《青玉案·元夕》· 宋代 · 辛弃疾\r\n  - text: 江山代有才人出，各领风骚数百年。\r\n    from: 《论诗五绝·其二》· 清代 · 赵翼\r\n\r\n# banner 背景图\r\n# 默认使用主题自带的图片（themes/cnblog/source/images/banner.webp），\r\n# 原博客园那份 CDN 图有防盗链，外站引用会 403，所以不能直接用。\r\n# 想换成自己的图：用后台上传拿到 /images/xxx.webp，再把这里改掉即可。\r\nbanner: /images/banner.webp\r\n\r\n# 头像\r\navatar: https://cdn.luogu.com.cn/upload/usericon/386597.png\r\n\r\n# 侧边栏简介\r\nintro: 这里是 FAKUMARER 的博客，记录算法竞赛、代码与生活。\r\n\r\n# 导航菜单\r\nmenu:\r\n  首页: /\r\n  归档: /archives/\r\n  分类: /categories/\r\n  标签: /tags/\r\n\r\n# 侧边栏显示的 widget 顺序（可注释掉不需要的）\r\nwidgets:\r\n  - profile\r\n  - stats\r\n  - categories\r\n  - tags\r\n  - recent\r\n\r\n# 页脚\r\nfooter:\r\n  since: 2026\r\n  copyright: FAKUMARER\r\n\r\n# 评论：配置不在主题里，在站点根目录 _config.yml 的 comments 段（后台「设置 → 评论」）。\r\n# 主题安装会整份覆盖本文件，放这里的话 repoId 每次都要重填。\r\n"
  },
  "assets": {
    "themes/cnblog/source/images/banner.webp": ""
  }
};
